import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_settings() -> dict[str, Any]:
    out: dict[str, Any] = {
        "confirmation_mode": "shadow",
        "time_zone": "Australia/Sydney",
        "cutoff_time": "",
        "delivery_days": "every_day",
        "missing_po": "customer_rule",
        "guessed_products": "always_ask",
        "unusual_quantity_factor": 5,
        "duplicate_window_days": 30,
        "substitutions": "never",
        "missing_unit": "ask",
    }
    try:
        saved = dict(api.extension.settings() or {})
    except Exception:
        saved = {}
    for key, value in saved.items():
        if value is not None and value != "":
            out[key] = value
    return out


import difflib

order_id = params["order_id"]
sender_email = od_text(params.get("sender_email")).lower()
customer_name = od_text(params.get("customer_name"))
hint = od_text(params.get("account_code")).upper()
domain = sender_email.split("@")[-1] if "@" in sender_email else ""
profiles = od_rows("od_customer_profiles")
chosen: dict[str, Any] = {}
match_how = "none"
for row in profiles:
    if hint and od_text(od_data(row).get("account_code")).upper() == hint:
        chosen = row
        match_how = "account_code"
        break
if not chosen and domain:
    hits = [r for r in profiles if od_text(od_data(r).get("email_domain")).lower() == domain]
    if len(hits) == 1:
        chosen = hits[0]
        match_how = "email_domain"
if not chosen and customer_name:
    wanted = od_norm(customer_name)
    best = 0.0
    for row in profiles:
        names = [od_text(row.get("title"))] + re.split(r"[;,\n]+", od_text(od_data(row).get("other_names")))
        for name in names:
            known = od_norm(name)
            if not known:
                continue
            if known == wanted:
                score = 1.0
            elif known in wanted or wanted in known:
                score = 0.95
            else:
                score = difflib.SequenceMatcher(None, known, wanted).ratio()
            if score > best:
                best = score
                if score >= 0.86:
                    chosen = row
                    match_how = "name" if score >= 0.95 else "name_guess"
customer_found = bool(chosen)
profile = od_data(chosen)
account_code = od_text(profile.get("account_code"))
known_name = od_text(chosen.get("title")) if chosen else ""
order_notes = od_text(profile.get("order_notes"))
order_rules = od_text(profile.get("order_rules"))
cutoff_time = od_text(profile.get("cutoff_time"))
po_required = bool(profile.get("po_required"))
